681	/// Called when focus is gained or lost (when focus events are enabled)
682	pub fn focusGained(self: *Termio, td: *ThreadData, focused: bool) !void {
683	    self.renderer_state.mutex.lockUncancelable(global.io());
684	    const focus_event = self.renderer_state.terminal.modes.get(.focus_event);
685	    self.renderer_state.mutex.unlock(global.io());
686	
687	    // If we have focus events enabled, we send the focus event.
688	    if (focus_event) {
689	        var buf: [terminalpkg.focus.max_encode_size]u8 = undefined;
690	        var writer: std.Io.Writer = .fixed(&buf);
691	        terminalpkg.focus.encode(&writer, if (focused) .gained else .lost) catch |err| {
692	            log.err("error encoding focus event err={}", .{err});
693	            return;
694	        };
695	        try self.queueWrite(td, writer.buffered(), false);
696	    }
697	
698	    // We always notify our backend of focus changes.
699	    try self.backend.focusGained(td, focused);
700	}
